library(driftwatch); for (s in 21:25) { sim <- dw_simulate(n_items = 150, n_windows = 30, seed = s); est <- dw_estimate(sim$responses, sim$bank); st <- sim$truth$type == "stable"; zs <- est$z[st, ]; ref_err <- (sim$bank$b - sim$b_path[, 1])[st]; cat(s, "mean z", round(mean(zs, na.rm=TRUE), 3), "sd", round(sd(zs, na.rm=TRUE), 3), "| mean bank error", round(mean(ref_err), 4), "| mean z w/o bank err", round(mean((est$b_hat[st, ] - sim$b_path[st, 1]) / est$se[st, ], na.rm=TRUE), 3), "\n") }
